    parser.add_argument('--output-root',type=Path,help='Fresh owned external metadata directory; creates only a pinned index under the round stem')
    args=parser.parse_args()
    if not re.fullmatch(r'[A-Za-z0-9_-]+',args.round):raise SystemExit('Invalid round')
    index=ROOT/args.round
    if index.exists():raise SystemExit('Preserve prior catalog index')
    out=index
    if args.output_root is not None:
        owned=(Path.home()/'.codex/artifact-archives/god2-server').resolve()
        requested=args.output_root
        if not requested.is_absolute() or not requested.resolve().is_relative_to(owned) or requested.resolve()==owned:
            raise SystemExit('External metadata must be an absolute descendant of the owned artifact archive')
        out=requested.resolve()
        if out.exists() or args.archive_root is None:raise SystemExit('Fresh metadata and full external input archive required')
    archive=args.archive_root
    if archive is not None:
        owned=(Path.home()/'.codex/artifact-archives/god2-server').resolve()
        if not archive.is_absolute() or not archive.resolve().is_relative_to(owned) or archive.resolve()==owned:
            raise SystemExit('Archive must be an absolute descendant of the owned artifact archive')
        archive=archive.resolve()
        if archive.exists():raise SystemExit('Preserve prior full archive')
        if args.output_root is not None and (out.is_relative_to(archive) or archive.is_relative_to(out)):
            raise SystemExit('Metadata and full input archive directories must be disjoint')
    archive_rows=[]
    def write_full(path,raw):
        path.parent.mkdir(parents=True,exist_ok=True)
        with path.open('xb') as handle:handle.write(raw)
        if archive is not None and path.is_relative_to(archive):
            archive_rows.append(dict(path=str(path),bytes=len(raw),sha256=hashlib.sha256(raw).hexdigest()))
    def snapshot_path(path):return str(path) if archive is not None else path.relative_to(out).as_posix()
    inputs=[]
    def read(path,key):
        raw=path.read_bytes();inputs.append((key,path,raw))
        return json.loads(raw.decode('utf-8-sig'))
